 *   }
 *   .panel:many {}
 * }
 */
.pfx-tabs {
  display: flex;
  flex-direction: column;
  background: var(--instui-component-tabs-default-background);
}

@scope (.pfx-tabs) {
  :scope {
    > .list {
      display: flex;
      width: 100%;
