const fs = require('fs');
const data = JSON.parse(fs.readFileSync('/Users/dwahl/Scripts/pantoken/formats/tokens/generated/rebrand.json', 'utf8'));

// Get all banner tokens
const bannerTokens = data.filter(t => t.name.includes('component-banner')).sort((a, b) => a.name.localeCompare(b.name));

// Group by category
const categories = {};
bannerTokens.forEach(t => {
  const parts = t.name.split('-');
  let category = 'other';
  if (t.name.includes('font') || t.name.includes('weight') || t.name.includes('height') || t.name.includes('family')) category = 'typography';
  else if (t.name.includes('background') || t.name.includes('color')) category = 'color';
  else if (t.name.includes('padding') || t.name.includes('gap') || t.name.includes('margin')) category = 'spacing';
  else if (t.name.includes('border')) category = 'border';
  else if (t.name.includes('icon')) category = 'icon';

  if (!categories[category]) categories[category] = [];
  categories[category].push(t);
});

Object.keys(categories).sort().forEach(cat => {
  console.log(\`\n## \${cat}\`);
  categories[cat].forEach(t => {
    console.log(\`  \${t.name}: \${t.value}\`);
  });
});
"

