  expect(Object.keys(first).sort()).toEqual(
    auditRecords()
      .map((record) => record.name)
      .sort(),
  );
  expect(auditFingerprints()).toEqual(first);
  expect(new Set(Object.values(first)).size).toBeGreaterThan(1);
});

