  expect(isSelected(undefined, "button")).toBe(true);
  expect(isSelected("button", "button")).toBe(true);
  expect(isSelected("button", "alert")).toBe(false);
  expect(isSelected(["button", "alert"], "alert")).toBe(true);
  expect(isSelected(["button"], "alert")).toBe(false);
});

